mapper.select:
SELECT COALESCE(SUM(CASE WHEN le.entry_type = 'income' THEN le.amount_cent ELSE 0 END),0) / 100.0 AS totalIncome,
       COALESCE(SUM(CASE WHEN le.entry_type = 'expense' THEN le.amount_cent ELSE 0 END),0) / 100.0 AS totalExpense,
       (COALESCE(SUM(CASE WHEN le.entry_type = 'income' THEN le.amount_cent ELSE 0 END),0) - COALESCE(SUM(CASE WHEN le.entry_type = 'expense' THEN le.amount_cent ELSE 0 END),0)) / 100.0 AS netIncome
FROM ledger_entry le
LEFT JOIN order_main om ON om.order_id = le.order_id
    AND om.camp_id = le.camp_id
    AND om.is_deleted = 0
WHERE le.camp_id = #{campId}
AND le.occurred_at >= #{beginTime}
AND le.occurred_at <= #{endTime}
AND om.room_category_id = #{roomCategoryId}


        AND le.entry_type = 'income'
        AND le.entry_type = 'expense'

mapper.sql:
WHERE doo.camp_id = #{campId}
  AND om.camp_id = #{campId}
  AND om.is_deleted = 0

    AND om.created_at >= #{bookingStart}


    AND om.created_at < #{bookingEndExclusive}


    AND (
        om.out_order_no LIKE CONCAT('%', #{keyword}, '%')
        OR om.order_no LIKE CONCAT('%', #{keyword}, '%')
        OR COALESCE(om.guest_name, '') LIKE CONCAT('%', #{keyword}, '%')
        OR COALESCE(om.guest_mobile, '') LIKE CONCAT('%', #{keyword}, '%')
        OR COALESCE(rc.name, '') LIKE CONCAT('%', #{keyword}, '%')
        OR COALESCE(rc.display_name, '') LIKE CONCAT('%', #{keyword}, '%')
    )


    AND doo.settlement_status = #{settledState}




            AND COALESCE(TRIM(om.remark), '') = '置换订单'


            AND COALESCE(TRIM(om.remark), '') != '置换订单'

mapper.select:
SELECT DATE_FORMAT(le.biz_date, '%Y-%m-%d') AS bizDate, CAST(COALESCE(le.payment_way_id, 0) AS CHAR) AS paymentWayId, COALESCE(pw.payment_way_name, '未指定') AS paymentWayName, COALESCE(pw.sort_no, 999999) AS sortNo, COALESCE(SUM(CASE WHEN le.entry_type = 'income' THEN le.amount_cent ELSE 0 END), 0) AS incomeAmountCent, COALESCE(SUM(CASE WHEN le.entry_type = 'expense' THEN le.amount_cent ELSE 0 END), 0) AS expendAmountCent FROM ledger_entry le LEFT JOIN payment_way pw ON pw.payment_way_id = le.payment_way_id AND pw.camp_id = le.camp_id AND pw.is_deleted = 0 WHERE le.camp_id = #{campId} AND le.biz_date >= #{beginDate} AND le.biz_date <= #{endDate}
AND le.poi_id IN
#{poiId}
GROUP BY le.biz_date, le.payment_way_id, pw.payment_way_name, pw.sort_no ORDER BY le.biz_date ASC, sortNo ASC, le.payment_way_id ASC

