mapper.select:
SELECT CAST(gm.goods_id AS CHAR) AS productId, CAST(dp.distribution_product_id AS CHAR) AS promotionPlanProductId, CAST(gm.camp_id AS CHAR) AS campId, gm.name AS name, ( SELECT COALESCE(m.media_url, mr.url) FROM goods_room_category_rel rel JOIN room_category_media m ON m.room_category_id = rel.room_category_id AND m.status = 1 LEFT JOIN media_resource mr ON mr.media_resource_id = m.media_resource_id AND mr.is_deleted = 0 WHERE rel.goods_id = gm.goods_id ORDER BY CASE WHEN m.scene_type = 'cover' THEN 0 ELSE 1 END, m.sort_no ASC, m.media_id ASC LIMIT 1 ) AS mainPhotoMediaUrl, CAST(JSON_UNQUOTE(JSON_EXTRACT(dp.commission_rule_json, '$.directRatio')) AS SIGNED) AS directRatio, CAST(JSON_UNQUOTE(JSON_EXTRACT(dp.commission_rule_json, '$.parentRatio')) AS SIGNED) AS parentRatio, CASE WHEN gm.goods_type IN ('coupon', 'presale', 'hotel_package') OR gm.room_category_type = 2 THEN 1 ELSE 0 END AS type, CASE WHEN dp.status = 1 THEN 1 ELSE 0 END AS state FROM distribution_product dp JOIN goods_main gm ON gm.goods_id = dp.goods_id AND gm.camp_id = dp.camp_id AND gm.is_deleted = 0 AND gm.status = 'published' WHERE dp.camp_id = #{campId}
AND CASE WHEN gm.goods_type IN ('coupon', 'presale', 'hotel_package') OR gm.room_category_type = 2 THEN 1 ELSE 0 END = #{type}
AND gm.name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY dp.distribution_product_id ASC

SELECT COUNT(DISTINCT crcr.room_category_id)
FROM channel_room_category_rel crcr
JOIN channel_account ca ON ca.account_id = crcr.account_id
WHERE crcr.camp_id = #{campId}
  AND ca.channel_id = #{channelId}

SELECT COUNT(1)
FROM order_main om
WHERE om.camp_id = #{campId}
  AND om.channel_id = #{channelId}
  AND om.is_deleted = 0

  AND DATE(om.created_at) = #{bizDate}

SELECT COUNT(1)
FROM shift_work_config
WHERE camp_id = #{campId}
  AND name = #{name}
  AND status = 1

  AND shift_config_id != #{excludedId}

SELECT COUNT(1)
FROM shift_work_goods
WHERE camp_id = #{campId}
  AND name = #{name}
  AND status = 1

  AND shift_goods_id != #{excludedId}

SELECT COUNT(1)
FROM pms_member
WHERE camp_id = #{campId}
  AND is_deleted = 0
  AND status = 1
  AND COALESCE(user_id, member_id) = #{userId}
